="flex items-center gap-space-lg"><a class="font-label-spec text-label-spec text-outline hover:text-on-surface transition-colors" data-path="home" href="/privacy">Privacy Telemetry</a><a class="font-label-spec text-label-spec text-outline hover:text-on-surface transition-colors" data-path="home" href="/terms">Terms of Hardware Service</a><a class="font-label-spec text-label-spec text-outline hover:text-on-surface transition-colors" data-path="home" href="/sitemap">Node Map</a></div></div></div></footer><script>
(function () {
  const product = document.getElementById('product_id');
  const quantity = document.getElementById('quantity');
  const fmt = new Intl.NumberFormat('vi-VN', {style:'currency',currency:'VND',maximumFractionDigits:0});
  function refresh() {
    const opt = product.options[product.selectedIndex];
    const price = Number(opt?.dataset.price || 0);
    const stock = Number(opt?.dataset.stock || 0);
    const qty = Number(quantity.value || 0);
    document.getElementById('order-product').textContent = product.value ? opt.textContent.split(' — ')[0] : 'Chưa chọn';
    document.getElementById('order-quantity').textContent = String(qty);
    document.getElementById('order-price').textContent = fmt.format(price);
    document.getElementById('order-stock').textContent = product.value ? String(stock) : '—';
    document.getElementById('order-total').textContent = fmt.format(price * qty);
    document.getElementById('checkout-submit').disabled = !product.value || qty < 1 || qty > 10 || qty > stock;
  }
  product.addEventListener('change', refresh);
  quantity.addEventListener('input', refresh);
  refresh();
})();
</script></body></html>